using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Siyue;
using Xunit;
public partial class AcademicBetaTests {
 static HomeworkGradeResult RetestGrade(JsonElement plan, params string[] verdicts)=>new("test","fixture",plan.GetProperty("body").GetProperty("exercises").EnumerateArray().Select((x,i)=>new HomeworkGradeQuestion((i+1).ToString(),"测试答案",verdicts[i],null,null,.99m,"教师验收用判定",["知识点"],x.GetProperty("question").GetProperty("stem").GetString()!)).ToArray(),[]);
 static async Task<(Guid SourceId,string SourcePath,string SourceReceipt,Guid JobId,JsonElement Plan)> TrainingDraft(WorkflowFactory f,HttpClient teacher,HttpClient reviewer,Guid classId,Guid studentId){
  var(id,path)=await ApprovedCollection(teacher,reviewer,classId);await Put(reviewer,Api+"/collections/"+id+"/learning-policy",new{revision=0,referenceAnswer="1.3x+5=20，x=5。2.1/2+1/3=5/6。",subject="数学",stage="初中",enabled=true});
  var receipt=(await Factory.Post(f.CreateClient(),path+"/begin",new{})).GetProperty("receipt").GetString()!;using(var photo=Photo(receipt,0,"first"))Assert.Equal(HttpStatusCode.OK,(await f.CreateClient().PostAsync(path+"/submit",photo)).StatusCode);
  f.Grader.Next=new("test","fixture",[new("1","x=2","incorrect",null,null,.99m,"计算错误",["一元一次方程"],"解方程3x+5=20。"),new("2","2/5","incorrect",null,null,.99m,"通分错误",["异分母分数加法","通分","最简分数"],"计算分数加法1/2+1/3，结果化为最简分数。")],[]);await f.Tick();
  var sub=(await Get(teacher,Api+"/collections/"+id+"/learning")).GetProperty("submissions")[0];var job=sub.GetProperty("job");await Put(teacher,Api+"/collection-submissions/"+sub.GetProperty("id").GetGuid()+"/student",new{revision=1,studentId});var jobId=job.GetProperty("id").GetGuid();await Factory.Post(reviewer,Api+"/grading-jobs/"+jobId+"/review",new{revision=job.GetProperty("revision").GetInt32(),confirmed=true});
  var plan=await Factory.Post(teacher,Api+"/grading-jobs/"+jobId+"/training",new{perError=2,maxQuestions=4});Assert.Equal(4,plan.GetProperty("body").GetProperty("exercises").GetArrayLength());return(id,path,receipt,jobId,plan);
 }
 [Fact] public async Task Training_retest_full_loop_is_review_gated_identity_scoped_and_counts_latest_evidence(){
  using var f=new WorkflowFactory();var x=await Seed(f);using var t=await f.Login("beta-author");using var r=await f.Login("beta-reviewer");using var parent=f.CreateClient();var before=await OriginalBusinessSnapshot(f);var source=await TrainingDraft(f,t,r,x.ClassId,x.StudentId);var planId=source.Plan.GetProperty("id").GetGuid();var route=Api+"/homework-trainings/"+planId;
  Assert.Equal(HttpStatusCode.Conflict,(await r.PostAsJsonAsync(route+"/retest",new{revision=0,confirmed=true})).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await t.PostAsJsonAsync(route+"/review",new{revision=0,confirmed=true})).StatusCode);
  var approved=await Factory.Post(r,route+"/review",new{revision=0,confirmed=true});var retest=approved.GetProperty("retest");var cid=retest.GetProperty("collectionId").GetGuid();var path="/academic-pilot/collect/"+retest.GetProperty("sharePath").GetString()!.Split("?t=")[1];
  var again=await Factory.Post(r,route+"/retest",new{revision=1,confirmed=true});Assert.Equal(cid,again.GetProperty("collectionId").GetGuid());
  var pub=await Get(parent,path);Assert.Equal(4,pub.GetProperty("questions").GetArrayLength());Assert.DoesNotContain("referenceAnswer",pub.ToString());Assert.DoesNotContain("analysis",pub.ToString());
  var detail=await Get(t,Api+"/collections/"+cid);Assert.Equal(1,detail.GetProperty("students").GetArrayLength());Assert.Equal(x.StudentId,detail.GetProperty("students")[0].GetProperty("id").GetGuid());
  Assert.Equal(HttpStatusCode.Conflict,(await r.PutAsJsonAsync(Api+"/collections/"+cid+"/learning-policy",new{revision=1,referenceAnswer="changed",subject="数学",stage="初中",enabled=true})).StatusCode);
  var receipt=(await Factory.Post(parent,path+"/begin",new{})).GetProperty("receipt").GetString()!;var answers=Enumerable.Range(1,4).Select(i=>new{label=i.ToString(),answer="测试答案"}).ToArray();var input=new{receipt,revision=0,name="本班学生甲",requestKey="a1",answers};await Factory.Post(parent,path+"/answers",input);await Factory.Post(parent,path+"/answers",input);
  f.Grader.Next=RetestGrade(source.Plan,"correct","correct","incorrect","correct");await f.Tick();var read=Api+"/collections/"+cid+"/learning";var view=await Get(t,read);var sub=view.GetProperty("submissions")[0];var job=sub.GetProperty("job");Assert.Equal(0,view.GetProperty("retest").GetProperty("passed").GetInt32());
  await Factory.Post(r,Api+"/grading-jobs/"+job.GetProperty("id").GetGuid()+"/review",new{revision=job.GetProperty("revision").GetInt32(),confirmed=true});Assert.Equal("pending_identity",(await Get(t,read)).GetProperty("retest").GetProperty("state").GetString());
  await Put(t,Api+"/collection-submissions/"+sub.GetProperty("id").GetGuid()+"/student",new{revision=1,studentId=x.StudentId});view=await Get(t,read);var progress=view.GetProperty("retest");Assert.Equal(3,progress.GetProperty("correct").GetInt32());Assert.Equal(1,progress.GetProperty("passed").GetInt32());Assert.Equal(1,progress.GetProperty("needsPractice").GetInt32());
  // One receipt is one attempt: an updated answer revokes the old mastery until re-reviewed.
  await Factory.Post(parent,path+"/answers",new{receipt,revision=2,name="本班学生甲",requestKey="a2",answers=Enumerable.Range(1,4).Select(i=>new{label=i.ToString(),answer="已订正"}).ToArray()});Assert.Equal(0,(await Get(t,read)).GetProperty("retest").GetProperty("passed").GetInt32());
  f.Grader.Next=RetestGrade(source.Plan,"correct","correct","correct","correct");await f.Tick();view=await Get(t,read);job=view.GetProperty("submissions")[0].GetProperty("job");await Factory.Post(r,Api+"/grading-jobs/"+job.GetProperty("id").GetGuid()+"/review",new{revision=job.GetProperty("revision").GetInt32(),confirmed=true});progress=(await Get(t,read)).GetProperty("retest");Assert.Equal(2,progress.GetProperty("passed").GetInt32());Assert.Equal(4,progress.GetProperty("correct").GetInt32());Assert.Equal(1,progress.GetProperty("submitted").GetInt32());
  using(var photo=Photo(receipt,3,"process-photo"))Assert.Equal(HttpStatusCode.OK,(await parent.PostAsync(path+"/submit",photo)).StatusCode);Assert.Equal(0,(await Get(t,read)).GetProperty("retest").GetProperty("passed").GetInt32());
  Assert.Equal(before,await OriginalBusinessSnapshot(f));using var outsider=await f.Login("beta-outsider");Assert.Equal(HttpStatusCode.NotFound,(await outsider.GetAsync(read)).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await parent.GetAsync(read)).StatusCode);
 }
 [Fact] public async Task Retest_rejects_missing_question_reviews_and_revokes_entry_when_original_changes(){
  using var f=new WorkflowFactory();var x=await Seed(f);using var t=await f.Login("beta-author");using var r=await f.Login("beta-reviewer");using var parent=f.CreateClient();var source=await TrainingDraft(f,t,r,x.ClassId,x.StudentId);var approved=await Factory.Post(r,Api+"/homework-trainings/"+source.Plan.GetProperty("id").GetGuid()+"/review",new{revision=0,confirmed=true});var retest=approved.GetProperty("retest");var cid=retest.GetProperty("collectionId").GetGuid();var path="/academic-pilot/collect/"+retest.GetProperty("sharePath").GetString()!.Split("?t=")[1];var receipt=(await Factory.Post(parent,path+"/begin",new{})).GetProperty("receipt").GetString()!;
  await Factory.Post(parent,path+"/answers",new{receipt,revision=0,name="本班学生甲",requestKey="a1",answers=Enumerable.Range(1,4).Select(i=>new{label=i.ToString(),answer="测试"}).ToArray()});f.Grader.Next=RetestGrade(source.Plan,"correct","correct","correct","uncertain");await f.Tick();var read=Api+"/collections/"+cid+"/learning";var job=(await Get(t,read)).GetProperty("submissions")[0].GetProperty("job");var jid=job.GetProperty("id").GetGuid();Assert.Equal(HttpStatusCode.Conflict,(await r.PostAsJsonAsync(Api+"/grading-jobs/"+jid+"/review",new{revision=2,confirmed=true})).StatusCode);
  var missing=f.Grader.Next with{Questions=f.Grader.Next.Questions.Take(3).ToArray()};await Put(r,Api+"/grading-jobs/"+jid,new{revision=2,result=missing});Assert.Equal(HttpStatusCode.Conflict,(await r.PostAsJsonAsync(Api+"/grading-jobs/"+jid+"/review",new{revision=3,confirmed=true})).StatusCode);
  // Editing original reviewed grading invalidates the downstream capability and its statistics.
  var original=(await Get(t,Api+"/collections/"+source.SourceId+"/learning")).GetProperty("submissions")[0].GetProperty("job");await Put(r,Api+"/grading-jobs/"+source.JobId,new{revision=original.GetProperty("revision").GetInt32(),result=original.GetProperty("result").Deserialize<HomeworkGradeResult>(Json.Options)});
  Assert.Equal(HttpStatusCode.Gone,(await parent.GetAsync(path)).StatusCode);Assert.Equal("stale",(await Get(t,read)).GetProperty("retest").GetProperty("state").GetString());Assert.Equal(HttpStatusCode.Gone,(await parent.PostAsJsonAsync(path+"/answers",new{receipt,revision=1,name="本班学生甲",requestKey="a2",answers=Array.Empty<object>()})).StatusCode);
 }
}
